    for layer in range(p_layers):
        for i in range(n):
            coefficient = 1.0 - penalty * degree[i] / 2.0
            if coefficient != 0.0:
                circuit.rz(coefficient * gamma[layer], i)
        for u, v in edges:
            circuit.rzz(penalty * gamma[layer] / 2.0, u, v)
