        circuit,
        basis_gates=gate_basis,
        optimization_level=1,
        seed_transpiler=seed % (2**32),
    )

    edge_masks = [(1 << u) | (1 << v) for u, v in edges]

    @lru_cache(maxsize=None)
    def state_statistics(mask):
        size = mask.bit_count()
        violations = sum(
            (mask & edge_mask) == edge_mask for edge_mask in edge_masks
        )
        return size, violations, -float(size) + penalty * violations

    def sample(parameters, shots):
        parameter_values = {
            gamma[layer]: float(parameters[layer])
            for layer in range(p_layers)
        }
        parameter_values.update(
            {
                beta[layer]: float(parameters[p_layers + layer])
                for layer in range(p_layers)
            }
        )
        bound = compiled.assign_parameters(parameter_values, inplace=False)
        result = simulator.run(
            bound,
            shots=shots,
            seed_simulator=int(sampling_rng.integers(1, 2**31 - 1)),
        ).result()
        if not result.success:
            raise RuntimeError(f"Aer simulation failed: {result.status}")

        # Qiskit displays the highest classical bit on the left. Interpreting
        # the string as an integer makes bit i correspond to vertex vertices[i].
        counts = {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in result.get_counts().items()
        }
        if sum(counts.values()) != shots:
            raise RuntimeError("Simulator returned an unexpected shot count.")
        return counts

    evaluations = 0
    best_energy = math.inf
    best_parameters = None

    def objective(parameters):
        nonlocal evaluations, best_energy, best_parameters
        counts = sample(parameters, opt_shots)
        evaluations += 1
        energy = sum(
            count * state_statistics(mask)[2] for mask, count in counts.items()
        ) / opt_shots
        if energy < best_energy:
            best_energy = float(energy)
            best_parameters = np.asarray(parameters, dtype=float).copy()
        return float(energy)

    initial_parameters = np.concatenate(
        [
            initialization_rng.uniform(0.0, np.pi / penalty, p_layers),
            initialization_rng.uniform(0.0, np.pi, p_layers),
        ]
    )
    optimization = minimize(
        objective,
        initial_parameters,
        method="COBYLA",
        options={"maxiter": maxiter, "rhobeg": 0.5, "tol": 1e-3},
    )
    if best_parameters is None:
        raise RuntimeError("The optimizer did not evaluate any parameters.")

    # Fresh final shots are not pooled with optimization shots.
    final_counts = sample(best_parameters, final_shots)
    valid_counts = {
        mask: count
        for mask, count in final_counts.items()
        if state_statistics(mask)[1] == 0
    }
    valid_shots = sum(valid_counts.values())
    best_mask = (
        min(valid_counts, key=lambda mask: (-mask.bit_count(), mask))
        if valid_counts
        else 0
    )
    sampled_size = best_mask.bit_count()
    if sampled_size > optimal_size:
        raise ValueError(
            "A sampled independent set exceeds optimal_independent_set_size; "
            "the supplied optimum is incorrect."
        )

    best_set = [vertices[i] for i in range(n) if best_mask & (1 << i)]
    optimal_shots = sum(
        count
        for mask, count in valid_counts.items()
        if mask.bit_count() == optimal_size
    )
    final_energy = sum(
        count * state_statistics(mask)[2]
        for mask, count in final_counts.items()
    ) / final_shots

    gate_counts = {
        str(name): int(count) for name, count in compiled.count_ops().items()
    }
    one_qubit_gates = 0
    two_qubit_gates = 0
    for instruction in compiled.data:
        if instruction.operation.name in {"measure", "barrier"}:
            continue
        if instruction.operation.num_qubits == 1:
            one_qubit_gates += 1
        elif instruction.operation.num_qubits == 2:
            two_qubit_gates += 1

    optimization_shots = evaluations * opt_shots
    total_shots = optimization_shots + final_shots

    return {
        "independent_set_ratio": sampled_size / optimal_size,
        "validity_rate": valid_shots / final_shots,
        "embedding_overhead": compiled.num_qubits / n,
        "resource_cost": {
            "execution_model": "finite-shot Aer statevector simulation",
            "connectivity_model": "all-to-all gate-model compilation",
            "logical_qubits": n,
            "modeled_physical_qubits": compiled.num_qubits,
            "ancilla_qubits": compiled.num_qubits - n,
            "qaoa_layers": p_layers,
            "variational_parameters": 2 * p_layers,
            "cost_interactions_per_layer": len(edges),
            "gate_basis": gate_basis,
            "compiled_gate_counts": gate_counts,
            "compiled_depth_including_measurement": int(compiled.depth()),
            "one_qubit_gates_per_shot": one_qubit_gates,
            "two_qubit_gates_per_shot": two_qubit_gates,
            "optimization_circuit_executions": evaluations,
            "final_circuit_executions": 1,
            "optimization_shots": optimization_shots,
            "final_shots": final_shots,
            "total_shots": total_shots,
