            ),
        },
        "best_independent_set": best_set,
        "best_independent_set_size": sampled_size,
        "best_set_observed_in_final_samples": bool(valid_counts),
        "optimal_independent_set_size": optimal_size,
        "optimal_solution_probability": optimal_shots / final_shots,
        "final_mean_penalized_cost": float(final_energy),
        "optimized_parameters": {
