        for u, v in combinations(vertices, 2)
        if math.dist(coordinates_um[u], coordinates_um[v])
        <= blockade_radius_um
    }
    if geometric_edges != set(edges) or len(edges) != 20:
        raise RuntimeError("The supplied graph disagrees with the blockade geometry.")

    # The corners {0,2,6,8} form an independent set of size four.
    # An upper bound of four follows from this partition into four cliques:
    # {0,1,3,4}, {2,5}, {6,7}, {8}. At most one vertex per clique is allowed.
    certified_set = exact_maximum_independent_set(vertices, edges)
    if certified_set != [0, 2, 6, 8]:
        raise RuntimeError("Unexpected exact MIS certificate.")

    report = solve_mis_qaoa(
        vertices,
        edges,
        optimal_independent_set_size=len(certified_set),
    )
    report.update(
        {
            "maximum_simultaneous_excitations": len(certified_set),
            "certified_maximum_independent_set": certified_set,
            "blockade_radius_um": blockade_radius_um,
            "conflict_edge_count": len(edges),
        }
    )
    print(json.dumps(report, indent=2))


